import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.D0_YsCyK.js";const u=JSON.parse('{"title":"订阅","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription.md","filePath":"guide/subscription.md","lastUpdated":1794344781000}'),l={name:"guide/subscription.md"};function d(i,o,n,a,c,g){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h1><p><strong>订阅</strong> 页管理所有订阅链接。思路和 Sub-Store 一样：选好<strong>来源</strong>直接<strong>输出</strong>。每个订阅选一批落地，节点按原样下发，客户端拿到的格式按 UA 自动识别（也可以复制指定格式的链接）。</p><p>升级前的订阅链接会变成这里的“我的订阅”，链接不变；原来的订阅设置和共享用户也会自动迁移过来。</p><h2 id="订阅与凭据" tabindex="-1">订阅与凭据 <a class="header-anchor" href="#订阅与凭据" aria-label="Permalink to &quot;订阅与凭据&quot;">​</a></h2><p>所有订阅在同一个列表里，靠名称区分（例如“我的手机”“小明”）。</p><ul><li>新建的订阅都有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li>可以设到期日期（到期当天 23:59 后断开）和流量上限，留空就是不限；停用、到期或流量用完后，面板会把它的凭据从节点上删掉</li></ul><h2 id="导入到客户端" tabindex="-1">导入到客户端 <a class="header-anchor" href="#导入到客户端" aria-label="Permalink to &quot;导入到客户端&quot;">​</a></h2><p>点订阅打开详情，按客户端选择：<strong>点客户端直接唤起 App 导入</strong>，右侧按钮复制该格式的链接。也可以复制上面的通用链接，客户端按 UA 自动拿到对应格式。</p><table tabindex="0"><thead><tr><th>客户端</th><th>格式</th><th>一键导入</th></tr></thead><tbody><tr><td>Clash（Clash Verge、Mihomo Party、FlClash 等）</td><td>Clash / Mihomo 配置</td><td><code>clash://</code></td></tr><tr><td>sing-box（SFA / SFI / SFM）</td><td>sing-box 配置</td><td><code>sing-box://</code></td></tr><tr><td>Shadowrocket</td><td>Clash 节点列表</td><td><code>shadowrocket://</code></td></tr><tr><td>Loon</td><td>Loon 节点</td><td><code>loon://</code></td></tr><tr><td>Quantumult X</td><td>QX 节点</td><td><code>quantumult-x://</code></td></tr><tr><td>Surge</td><td>Surge 配置</td><td><code>surge://</code></td></tr><tr><td>Stash</td><td>Stash 配置（Clash 档案，规则集为 YAML）</td><td><code>stash://</code></td></tr><tr><td>通用</td><td>Base64 分享链接（v2rayN、NekoBox 等）</td><td>仅复制</td></tr></tbody></table><ul><li>客户端不支持的协议会自动略过，例如 Loon 没有 TUIC，Quantumult X 没有 Hysteria2 / TUIC，Surge 没有 VLESS</li><li>指定格式的链接：在订阅链接后加 <code>?format=clash</code>（或 <code>singbox</code>、<code>shadowrocket</code>、<code>loon</code>、<code>qx</code>、<code>surge</code>、<code>stash</code>、<code>base64</code>）</li><li>VLESS 加密（ENC）入站只出现在 Clash / Stash / 通用 base64 输出里（携带完整 <code>encryption</code> 参数），其他格式会略过这类入站</li><li><strong>导入</strong>的 Snell 节点（经导入 / 订阅源进来的）按下端口径下发：<strong>Clash 格式</strong>下发 v3（带 http / tls 混淆的 v3 照常），v1 / v2 强制以 <code>udp: false</code> 下发（Snell 这两个版本本身不支持 UDP，mihomo 收到 <code>udp: true</code> 会整份拒绝），v4 / v5 <strong>不下发</strong>（mihomo 收到会把整份订阅拒绝），带 shadow-tls / restls / jls 混淆的节点<strong>不下发</strong>（mihomo 没有这三种混淆模式，收到同样整份拒绝）；<strong>Stash / Shadowrocket</strong> 照常下发 v1–v4、v5 归一为 v4 下发，但 <strong>v6 与负数等异常版本略过不下发</strong>；<strong>sing-box 格式</strong>只接受 v4 / v5（归一为 v4）/ v6 三档，<strong>v1 / v2 / v3 的导入 Snell 节点整节点略过、不下发</strong>，Snell + ShadowTLS 导入节点经 shadow-tls 转换（detour）下发（<code>shadow-tls</code> 键形态与 Clash YAML 导入的 <code>obfs-opts</code> 形态同口径），其余混淆形态（http / tls / restls / jls）sing-box 无从表达、不下发该节点。自检：拿一条含导入 Snell v5 节点的订阅拉取 Clash 格式，输出里不应出现该节点、其余节点应能被 mihomo 客户端正常加载</li><li>NaïveProxy 节点在 sing-box 订阅侧需要客户端 1.13 以上版本：按拉取请求的 UA 判定，低于 1.13 时不下发 NaïveProxy 节点、其余节点照常下发（sing-box 出站对 NaïveProxy 的支持自 1.13 起，节点侧链式门同见节点文档）。下发格式只有 sing-box（1.13 以上）与通用 base64 两种：base64 分享链接的形态按节点来源区分——面板自建入站以 <code>naive+https://</code> 形态携带，通过导入进来的 NaïveProxy 节点以 <code>naive://</code> 形态携带；其余格式（Clash、Stash、Shadowrocket、Loon、Quantumult X、Surge）不下发 NaïveProxy 节点</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li><strong>全部落地</strong>：包括以后新增的落地，不用再回来勾选</li><li><strong>指定落地</strong>：只勾选需要的，分“自建”“导入”和“订阅源”三组。订阅源按整个源勾选，以后更新进来的节点会自动跟上；没法只取某个订阅源里的一部分节点——要缩小范围，用下面的「中转范围」：三档按端点类型（直连 / 中转）分档，「自定义」档可逐端点勾选</li></ul><p>落地的中转线路会跟着它一起出现在订阅里。</p><ul><li><strong>只通过转发访问的节点（纯中转导入节点）不可订阅</strong>：订阅源勾了「新节点设为只通过我的转发访问」后，它导入的节点没有直连端点——把它们选入订阅也不会出现在订阅里（任何中转范围档位下都一样）；只有先给节点接上你的中转线路，它才经中转端点出现在订阅里。保存订阅时，所选节点里若有这种还没接中转的节点，回执会逐个点名提示；把订阅源存为纯中转源时，保存与同步回执也会提示该源的节点不可订阅。</li></ul><h2 id="中转范围" tabindex="-1">中转范围 <a class="header-anchor" href="#中转范围" aria-label="Permalink to &quot;中转范围&quot;">​</a></h2><p>订阅编辑页的 <strong>中转范围</strong> 决定这条订阅吐出哪些端点（先在上面的「来源」里选好落地），四档：</p><ul><li><strong>全部</strong>（默认）：所选落地的全部端点——直连加上全部中转，以后新增的中转也会自动跟上。</li><li><strong>只要直连</strong>：只保留直连端点。</li><li><strong>只要中转</strong>：只保留经中转的端点。</li><li><strong>自定义</strong>：逐端点勾选（直连与各条中转线逐个勾），只下发勾中的端点；勾选集（白名单）非空时优先于上面三档。<strong>全不勾时不下发空订阅</strong>：勾选集为空时按保存时的三档回落下发（「全部」／「只要中转」／「只要直连」），保存回执会点名此次回落；重开编辑时空集不保留、回到三档显示。</li><li><strong>生效方式</strong>：过滤在每次拉取时按订阅保存的设置在服务端执行，保存后下一次拉取即生效，不用换链接。它和下文「分配给用户与撤销」是两个维度：中转范围是订阅自身的属性，对该订阅的全部持有者一视同仁，收紧或放宽都会同时影响所有已复制走的链接下一次拉到的内容；想只改某个人的端点范围做不到，只能为他单独建一条订阅。</li><li><strong>存量白名单</strong>：2.1.2 之前的中转范围是端点白名单（逐个勾选端点）。2.1.3 起折算逻辑已删除、白名单恢复精确语义：白名单非空时按下发的勾选集原样过滤、优先于三档。<strong>升级须知</strong>：未在 2.1.2 编辑器里重存过的订阅，装 2.1.3 后自动按原白名单复活；已在 2.1.2 编辑器里重存过的订阅白名单已丢，须在新「自定义」档里手动重勾一次。</li><li><strong>自检</strong>：保存后拉取一次该订阅，数一下端点是否只剩所选档位的那些。</li></ul><h2 id="订阅源" tabindex="-1">订阅源 <a class="header-anchor" href="#订阅源" aria-label="Permalink to &quot;订阅源&quot;">​</a></h2><p>在 <strong>落地 → 订阅源</strong> 添加机场或别人的订阅链接，相当于 Sub-Store 的远程订阅。也可以在 <strong>落地 → 导入</strong> 里粘贴订阅地址，打开 <strong>定时同步</strong>（默认打开）就会存成订阅源；关掉则只导入一次：</p><ul><li>添加后立即拉取一次，节点出现在 <strong>落地</strong> 页“订阅源 · 名称”分组里，可以和其他导入节点一样检测、接中转、放进订阅</li><li><strong>自动更新</strong>：手动 / 6 小时 / 12 小时 / 每天。也可以点卡片右边的按钮立即更新。面板每 10 分钟检查一次到期的订阅源，实际同步时刻最迟可能比设定间隔晚约 10 分钟</li><li>更新时按 <strong>名称</strong> 对上已有节点（名称变了再按地址对）：地址变了就跟着改，挂在上面的中转也会改到新地址；订阅里没有了就删除，但挂着中转的会保留，免得中转断掉</li><li>拉取失败或返回空内容时保留现有节点，卡片上显示错误</li><li>机场返回的流量和到期信息（<code>Subscription-Userinfo</code>）会显示在卡片上</li><li><strong>上传文件</strong>：拿不到订阅链接时，可以给订阅源直接上传订阅文件（Base64、Clash / Mihomo、sing-box 格式均可，上限 5MB）；文件源不自动更新，要更新时在卡片上点「重新上传」</li><li><strong>用途</strong>：订阅源可以标成 <strong>中转</strong> 或 <strong>落地</strong>（默认普通），作为来源的用途标记，便于在订阅的来源里区分挑选</li><li><strong>新节点设为只通过我的转发访问</strong>：新加进来的节点只用来接中转，不直接进订阅；这类节点不可订阅（口径见「来源」一节），把源存成纯中转源时回执会给出提示</li><li>删除订阅源时可以选连同节点一起删除，或只删订阅源、节点留下变成普通的导入节点</li><li><strong>手工删除单个导入节点是粘性的</strong>：在「落地」页删掉某个订阅源节点后，该节点会被登记为已屏蔽，订阅源之后的同步（自动更新或点按钮立即更新）<strong>不会把它重新建回来</strong>，删节点的回执会提示这一口径，源的同步结果里也会点名本次跳过的已屏蔽条数。屏蔽只针对被删的那一个条目本身：源里把这个节点<strong>改名或改地址</strong>后，它会被当作新节点正常同步进来、不受旧屏蔽影响；删除整个订阅源时，它的屏蔽登记一并清掉；用批量删除删掉的导入节点同样逐个登记屏蔽，口径与单个删除一致</li></ul><p>典型用法：订阅选“指定落地”，勾上自己的落地和机场订阅源，一个链接全搞定。</p><h2 id="订阅模板" tabindex="-1">订阅模板 <a class="header-anchor" href="#订阅模板" aria-label="Permalink to &quot;订阅模板&quot;">​</a></h2><p>想让订阅完全按自己的规则集、策略组和 DNS 下发，可以用 <strong>订阅模板</strong>：把一份 Mihomo、sing-box 或 Surge 的完整配置当骨架，面板只负责把订阅节点填进策略组，其余内容原样下发，不需要再套一层 subconverter。</p><p>入口：<strong>订阅</strong> 页右上角 <strong>模板</strong> → <strong>新建模板</strong>。每个模板只对应一种格式（Mihomo / sing-box / Surge），有三种建法：</p><ul><li><strong>选择规则</strong>（可视化构建器）：选规则预设（极简 / 均衡 / 完整 / 自定义）、勾选规则分类并逐条指定去向、调整规则顺序（从上往下匹配）、添加自定义规则（完整域名 / 域名后缀 / 域名关键词 / IP CIDR），再按需加地区测速组（香港、日本、美国等按节点名自动收节点）。「按服务生成独立策略组」默认开启，每个分类在客户端里是一个可单独选节点的组。保存时生成配置并存库；之后改配方要重新保存才生效。切到源码编辑会先把当前配方生成配置，手动改过并保存后该模板转为源码模板，不再能反向变回配方</li><li><strong>源码编辑</strong>：直接粘贴整份配置。节点列表留空即可（如 Mihomo 的 <code>proxies: []</code>），面板会填进去；内容为空时可点 <strong>用示例开始</strong></li><li><strong>从网址获取</strong>：填模板地址（如 GitHub 上的 raw 链接），面板先下载一次存库，之后 <strong>每天自动刷新一次</strong>；下载失败或内容校验不过时 <strong>继续用上次成功的内容并把错误记在模板行上</strong>，不会把用它的订阅打挂。网址模板不能直接改内容，点列表里的 <strong>复制为本地模板</strong> 得到一份可编辑副本</li></ul><p>节点怎么进策略组，按各客户端本来就支持的写法、模板里写好即可：</p><table tabindex="0"><thead><tr><th>格式</th><th>写法</th><th>说明</th></tr></thead><tbody><tr><td>Mihomo</td><td>策略组写 <code>include-all: true</code>，可加 <code>filter: &quot;(?i)港|HK&quot;</code>、<code>exclude-filter</code></td><td>客户端自己按 filter 收节点</td></tr><tr><td>sing-box</td><td>组里写 <code>&quot;{all}&quot;</code> 占位，可加 <code>&quot;filter&quot;: [{&quot;action&quot;: &quot;include&quot;, &quot;keywords&quot;: [&quot;港|HK&quot;]}]</code></td><td>面板下发时把 <code>{all}</code> 换成符合 filter 的节点名；组里一个节点都没有时，若模板里自带 <code>direct</code> 类型的出站，就换成该直连出站避免客户端报错——模板里没有 direct 出站时该组会以空组原样下发，所以自备 sing-box 模板请保留一个 direct 出站</td></tr><tr><td>Surge</td><td>组行写 <code>include-all-proxies=1</code>，可加 <code>policy-regex-filter=港|HK</code></td><td>客户端自己按正则收节点</td></tr></tbody></table><p>其他填充行为：Mihomo 只替换 <code>proxies</code> 段、模板其余文字（含注释与顺序）原样保留；sing-box 的节点追加在 <code>outbounds</code> 末尾、WireGuard 节点进 <code>endpoints</code>；Surge 的节点写在 <code>[Proxy]</code> 段原有内容之后、没有该段时自动补。节点名与模板组名重复时节点名加 <code>#2</code> 后缀。</p><p>在订阅里使用：编辑订阅 → <strong>订阅模板</strong>，给 Mihomo、sing-box、Surge、Stash、Shadowrocket 各选一个模板（Stash / Shadowrocket 用 Mihomo 格式的模板）：</p><ul><li>选了模板的客户端拿到按模板生成的配置；没选模板的客户端照旧走内置格式</li><li>Stash 没单独选时沿用 Mihomo 的模板；但 Mihomo 模板里有 <code>mrs</code> 规则集（Stash 读不了）时不沿用、改用内置渲染</li><li>Stash / Shadowrocket 不自己收 <code>include-all</code> 组，面板会把这类组展开成具体节点列表（模板里原本写的成员排在前面），一个都匹配不到时放 <code>DIRECT</code> 兜底</li><li>订阅的节点按原样填进模板（中转范围先生效：逐端点白名单非空时按白名单，否则按三档）</li><li>模板编辑里的 <strong>检查并预览策略组</strong> 可以选某个订阅，用它的节点预演每个策略组收到哪些节点；没有节点的组会提示为空组</li><li>防错：地区策略组按节点名收节点，过滤条件是 Go 正则（与 Mihomo 同口径的 regexp2）；填错了只在「检查并预览策略组」时才以「过滤条件无法预览」示出，编辑时输入框旁无提示——保存前先点检查。节点改名后，按名收节点的组会静默收不到它（组按名匹配，不跟改名），改名后须重查该组的成员。Mihomo 模板里某个组一个节点都没有时，保存会警告「策略组没有成员，Mihomo 会拒绝这份配置」，空组不要下发</li><li>有订阅在用的模板不能删除、也不能改格式；先在订阅里换掉</li></ul><h2 id="独立凭据" tabindex="-1">独立凭据 <a class="header-anchor" href="#独立凭据" aria-label="Permalink to &quot;独立凭据&quot;">​</a></h2><ul><li>每个订阅有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li><strong>停用</strong>、<strong>删除</strong> 或 <strong>到期</strong> 后，面板会把它的凭据从节点上删掉。拉取侧的回执分两种：停用、到期或流量用完时，链接仍返回 HTTP 200，但内容只剩一个写明原因的占位节点（<code>⚠️ 订阅已停用，请联系管理员</code> / <code>⚠️ 订阅已过期，请联系管理员</code> / <code>⚠️ 流量已用完，请联系管理员</code>），客户端据此把旧节点列表换掉、使用者能直接看到原因；只有<strong>删除</strong>订阅（以及重置后的旧链接）才是当场返回 404、拉不到任何内容。节点侧的凭据移除靠面板下发完成：节点在线时随即生效；节点离线、网络分区或下发失败期间，节点上仍保留旧凭据、已导入的配置仍可连接，直到节点重连后对账移除为止（下发失败时面板会持续重试，删除订阅下发失败时回执会提示）。但共用凭据的节点例外（Shadowsocks 和导入的节点，见下一条说明）：删除订阅只删链接、共用密码不变，对方已经导入的配置仍能连接</li><li><strong>重置链接和凭据</strong>：旧链接立即失效（面板侧校验，拉取当场被拒），适合链接泄露时使用；对方已导入配置里的旧凭据则要靠面板把新凭据下发到节点后才失效——节点离线时，旧配置在该节点重连对账之前仍可连接。但共用凭据的节点例外（Shadowsocks 和导入的节点）：它们用的是共用密码、重置不轮换，重置后对方已经导入的配置仍能连接，要断开只能改对应入站的密码</li><li>支持单独凭据的协议：VLESS、VMess、Trojan、Hysteria2、TUIC、AnyTLS、NaïveProxy。Shadowsocks 和导入的节点只能共用原来的密码：停用后订阅失效，但对方已经导入的配置仍能连接（界面上会标出“共用凭据”）</li><li>例外：Shadowsocks 2022 入站可以开启「按订阅计量」（见下文同名小节）。开启后订阅新拉取的配置改走独立凭据并计入流量统计与流量上限；开启前已分发的链接照常可用，但不计量</li><li>3 天内到期会推送 <a href="./notify">通知</a></li></ul><h3 id="流量上限" tabindex="-1">流量上限 <a class="header-anchor" href="#流量上限" aria-label="Permalink to &quot;流量上限&quot;">​</a></h3><ul><li>每个订阅单独统计流量（上传 + 下载），可以设 <strong>流量上限</strong>，用完自动断开，和到期一样</li><li><strong>每月重置</strong>：选每月几号，到那天 0 点自动清零；也可以在订阅详情里点 <strong>重置流量</strong> 手动清零，超限断开的会立即恢复</li><li>用到 90% 和用完时会推送 <a href="./notify">通知</a>，概览页的“需要处理”里也会列出</li><li>客户端里能看到已用流量、总量和到期时间（<code>Subscription-Userinfo</code>）</li><li>统计在落地节点上进行：每个订阅走自己的出站，节点用 nftables 计数，Xray 和 sing-box 都支持。需要节点上有 nftables，并且节点 agent 要和面板一起更新到最新版（旧 agent 能正常转发，只是不计数）</li><li>只统计支持单独凭据的协议。共用凭据的落地（导入的节点，以及未开启「按订阅计量」的 Shadowsocks）分不清是谁在用，不计入</li></ul><h3 id="流量统计" tabindex="-1">流量统计 <a class="header-anchor" href="#流量统计" aria-label="Permalink to &quot;流量统计&quot;">​</a></h3><p>订阅详情里有 <strong>流量统计</strong>：按小时（近 24 小时）、日（近 30 天）、月（近 12 个月）看这条订阅的上传、下载曲线。被分配了这条订阅的用户，在 <strong>我的订阅</strong> 里展开自己的订阅卡片也能看。</p><ul><li>曲线是 <strong>整条订阅的合计</strong>：一条订阅分给多人时，凭据是同一套，流量拆不到个人，每位被分配用户看到的是同一条合计曲线</li><li>统计口径和「已用」一致（只统计独立凭据协议与已开启计量的 Shadowsocks 2022，共用凭据不计入）</li><li>详情与「我的订阅」会标注统计的<strong>起算时间</strong>（订阅创建或上次重置流量之时），显示为「&lt;日期&gt; 起已用 …」；重置流量后起算时间随之更新，起算之前的时段不在统计内</li><li>自 1.3.0 起开始记录，上线之前的时段没有数据</li><li>小时级统计数据保留 400 天，更早的数据会被自动清理</li></ul><h3 id="shadowsocks-按订阅计量" tabindex="-1">Shadowsocks 按订阅计量 <a class="header-anchor" href="#shadowsocks-按订阅计量" aria-label="Permalink to &quot;Shadowsocks 按订阅计量&quot;">​</a></h3><p>Shadowsocks 原本是共用凭据，分不清每条订阅的流量。自建的 Shadowsocks 2022 入站可以在编辑入站时开启「按订阅计量」：</p><ul><li>开启后，面板在<strong>同一节点</strong>上为该入站生成一个计量专用入口（入站列表会显示「计量中」徽标）。订阅<strong>新拉取</strong>的配置自动改走这个入口并使用独立凭据，流量计入该订阅的统计与流量上限，和其他独立凭据协议一样。每个计量入站会在节点上多占一个伴生端口（在 [20000, 60000) 内随机取空闲端口（即 20000–59999、含 59999 不含 60000），不占节点配置的端口范围；端口被占用时错误信息会点名是计量伴生入站占用）</li><li><strong>已有链接不受影响</strong>：开启前分发的配置继续连原入口、照常可用，但不计量；想纳入计量，让使用者重新拉取一次订阅即可</li><li>订阅停用 / 删除 / 到期 / 超出流量上限后，计量入口上的对应凭据会照常被移除，重新拉取的配置随之断开</li><li>仅支持 2022 系列方法（如 <code>2022-blake3-aes-128-gcm</code>）。传统方法（如 <code>aes-256-gcm</code>）、ShadowTLS 前置的入站和导入的节点没有多用户能力，不在覆盖范围内</li><li>带链式出口、已配置分流、仅中转或开启了 PROXY 协议的入站不能开启计量（计量入口是独立直连入口，继承这些设置会把订阅流量静默改道）；已开启计量的入站要改成这些形态，需先关闭计量</li><li>从备份恢复后计量入口会以新凭据重建，此前分发的计量链接随之失效，需重新拉取订阅；手动降级到旧版本前的注意事项见 <a href="./upgrade#降级到旧版本-手动">升级 · 降级到旧版本</a></li><li>注意：持有共用密码的人仍可直连原入口绕过计量与上限（与开启前一致）。要彻底收口，可在大家重新拉取后更换原入站的共用密码——原密码分发的配置会随之失效，计量入口不受影响</li><li>例外：中转端点走原共用凭据、不按订阅计量——经中转（隧道）到达该入站的订阅端点不在计量覆盖内，其流量按隧道口径统计，不计入该订阅的统计与流量上限</li></ul><h2 id="分配给用户与撤销" tabindex="-1">分配给用户与撤销 <a class="header-anchor" href="#分配给用户与撤销" aria-label="Permalink to &quot;分配给用户与撤销&quot;">​</a></h2><p>管理员可以把订阅分配给指定用户（订阅分配），被分配的用户在自己的「我的订阅」里能看到并复制该订阅的链接。</p><p>撤销时注意链接的认凭据方式：<strong>订阅链接认的是订阅本身的 token，不认人</strong>。</p><ul><li>删掉某个用户的分配、禁用或删除该用户：只是让他在面板里看不到这个订阅，<strong>他此前已经复制走的链接仍可继续拉取使用</strong></li><li>例外：旧版生成的 <code>?user=</code> 个性化链接按分配关系出内容，与 token 链接口径不同——删分配或删用户后，它拉取返回 200 加一份<strong>空节点列表</strong>（内容被过滤为空、不是报错），不会再出该订阅的节点；<code>?user=</code> 在场但不是正整数（如 <code>abc</code>、<code>0</code>、<code>-1</code>）时同样返回 200 空节点列表，不会按裸 token 出全量</li><li>要断掉某个人已复制的链接，只能 <strong>重置订阅</strong>（链接和凭据一起轮换，旧链接立即失效）或 <strong>删除订阅</strong>；两者都会同时影响该订阅的全部持有者，无法只断一个人</li><li>停用订阅或订阅到期、流量用完：对全部持有者立即生效——他们下一次拉取拿到的是只含一个原因占位节点的配置（HTTP 200，真实节点不再下发，形态见 <a href="#独立凭据">独立凭据</a>）</li></ul><h2 id="订阅前置地址" tabindex="-1">订阅前置地址 <a class="header-anchor" href="#订阅前置地址" aria-label="Permalink to &quot;订阅前置地址&quot;">​</a></h2><p>面板域名可能被部分运营商阻断或烂路由，个别用户打不开面板、也拉不到订阅。前置地址就是给订阅链接准备的备用入口：同一条订阅换一个域名就能拉，内容和凭据都不变。</p><p>原理：服务端按链接里的 token 出订阅，<strong>与访问用的域名无关</strong>。前置只需把订阅路径反代回面板（自备一台反代机，或用 CDN 回源到面板域名），把它的地址填进设置，链接就能按前置地址生成。</p><p>设置方法（管理员）：推荐用面板机的管理脚本 + Cloudflare 完成（自备一台反代机回源到面板域名也可以，原理相同）：</p><ol><li><p>在面板机运行 <code>panel_install.sh</code>，选菜单 <strong>6「配置订阅前置域名（自动 HTTPS）」</strong>，按提示输入前置域名（如 <code>sub.example.com</code>）。前提是菜单 5 已给面板域名配好反代；脚本会往 Caddy 配置里追加前置域名的站点块并自动申请证书。</p></li><li><p>在 Cloudflare 给前置域名加 A 记录：进入该域名 → <strong>DNS → 记录 → 添加记录</strong>，类型选 <strong>A</strong>；「名称」只填子域名部分（相对于托管区，如托管区为 <code>example.com</code>、前置域名 <code>sub.example.com</code> 时填 <code>sub</code>）；IPv4 地址填面板机公网 IP（与面板域名指向的 IP 相同）；「代理状态」<strong>先关（仅 DNS、灰云）</strong>，等 Caddy 证书签发完成（<code>https://&lt;前置域名&gt;</code> 能打开）后，再回到这里改为「已代理」（橙云）。</p><blockquote><p><strong>域名层级警告</strong>：前置域名必须是<strong>一级子域名</strong>（如 <code>sub.example.com</code>），不要用二级子域名（如 <code>cloud.dy.example.com</code>）——Cloudflare 免费版的边缘证书只覆盖根域名与一级子域名（<code>example.com</code> 与 <code>*.example.com</code>），二级子域名开启橙云（代理）后，边缘证书与域名不匹配，客户端拉取时会报「证书无效 / 安全连接失败」，且在任何网络下都无法拉取。</p></blockquote></li><li><p>在 Cloudflare 建缓存绕过规则：进入该域名 → <strong>缓存 → Cache Rules → 创建规则</strong>，名称随意（如「订阅不缓存」）；匹配条件：字段选「<strong>URI 路径</strong>」，运算符选「通配符」、值填 <code>/api/v1/open_api/sub/*</code>（或运算符选「以…开头」、值填 <code>/api/v1/open_api/sub/</code>，两者等效）；下方「缓存资格」选「<strong>绕过缓存（Bypass cache）</strong>」，保存并部署，避免订阅内容被 CDN 缓存。可选收紧：再用 And 加一个「主机名 等于 &lt;前置域名&gt;」的条件，把规则只作用于前置域名。</p></li></ol><ul><li>注意：这条规则只覆盖 <code>/api/v1/open_api/sub/*</code>，旧的凭据订阅端点 <code>/api/v1/open_api/sub_store</code> 不在覆盖内（路径无 <code>/sub/</code> 前缀）；该端点不走 CF 绕过模式，但服务端本身对它下发 <code>Cache-Control: no-store</code>，不会被 CDN 缓存。 <blockquote><p>⚠️ 不要选「URI 完整（完整 URL）」字段填这个路径：它按整条 URL 全串匹配、永不命中，规则会静默失效。</p></blockquote></li></ul><ol start="4"><li>在面板填前置地址：<strong>网站配置 → 订阅前置地址</strong>（这一页在侧栏菜单里就叫「设置」，脚本菜单 6 的完成指引里说的也是同一页），点「添加前置地址」，可加多条。每条填 <code>https://&lt;前置域名&gt;</code>：以 <code>http://</code> 或 <code>https://</code> 开头（推荐 <code>https://</code>）、末尾不要斜杠、不要带任何路径（可带端口）；保存时会校验：必须是 http/https、不能带路径或查询参数，非法值会报错并拒绝保存；填入重复地址（含仅末尾斜杠之差）不会报错，会自动去重后保存。最多 20 条。</li><li>自检：规则部署后，用任意可达网络执行 <code>curl -sI &lt;一条前置订阅链接&gt; | grep -i cf-cache-status</code>，显示 <code>BYPASS</code> 即缓存规则已生效；也可以在拉不到订阅的网络下实拉一次订阅验证。</li></ol><p>使用：配置后，<strong>订阅</strong> 页、入站页的订阅卡和用户的 <strong>我的订阅</strong> 页里，链接旁会出现「链接地址」选择——默认是面板域名，也可以选任一前置地址；复制、二维码和导入客户端都按所选地址生成链接。不配置前置地址时，这些页面和之前完全一致。</p><p>注意：订阅链接里的 token 就是凭据，走前置意味着前置的运营方（如 CDN 服务商）在其日志里能看到完整链接（含 token）。只填自己可控或足够可信的前置；怀疑链接外泄时重置订阅，旧链接（含经前置复制走的）立即失效。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>点订阅可以导入到客户端、复制各种格式的链接、编辑、重置链接或删除</li><li>所有订阅都包含在 <strong>网站配置 → 数据备份与恢复</strong> 的“内核与入站”里</li><li>订阅当前没有可用节点时（节点全停用、被过滤光或订阅本身为空），拉取返回 HTTP 200 和一份<strong>空节点列表</strong>，而不是错误码——这是刻意的：返回 503 会被客户端当成订阅源故障并保留旧节点，返回空列表能让客户端及时清空</li><li>订阅被停用、到期或流量用完时，拉取同样返回 HTTP 200，但内容只剩一个写明原因的占位节点（形态见 <a href="#独立凭据">独立凭据</a>），客户端会把旧列表换成这条占位；只有删除订阅、或重置后的旧链接才返回 404</li></ul>',55)])])}const p=t(l,[["render",d]]);export{u as __pageData,p as default};
